  if($('#secureAuth'))$('#secureAuth').onsubmit=async e=>{e.preventDefault();let b=e.target.querySelector('button');b.disabled=true;try{const signup=productRoute==='signup';const data={email:$('#secureEmail').value,password:$('#securePassword').value};if(signup){data.name=$('#secureName').value.trim();if(!data.name)throw Error('Enter your name.');}const r=await api('/auth/'+(signup?'signup':'login'),'POST',data,false);if(signup){status('secureStatus',r.message);$('#securePassword').value=''}else if(r.confirmation_required){status('secureStatus',r.message);$('#securePassword').value=''}else if(r.mfa_required){location.hash='/mfa?token='+encodeURIComponent(r.challenge)}else{loadedProfile=null;location.hash='/'+authReturnTarget()}}catch(e){status('secureStatus',e.message)}finally{b.disabled=false}};
