  document.querySelectorAll('[data-revoke-session]').forEach(b=>b.onclick=async()=>{try{await api('/sessions/'+encodeURIComponent(b.dataset.revokeSession),'DELETE');await secureRoute()}catch(e){toast(e.message)}});
