   document.querySelectorAll('.modeBadge').forEach(el=>el.textContent=config.demo_mode?'LOCAL DEMO · SYNTHETIC ACCOUNTS':!me?'PUBLIC RESOURCES':config.free_beta?'FREE BETA · NO CHARGES':'SERVER SESSION');document.querySelectorAll('.accountFooter>span:first-child').forEach(el=>el.textContent=!me?'● Public resources · log in to save projects':config.free_beta?'● Free beta account':'● Account connected');document.querySelectorAll('[data-logout]').forEach(el=>el.textContent=me?'Log out':'Log in →');const firstMetric=document.querySelector('.dashboardMetrics .metric small');if(firstMetric)firstMetric.textContent='Projects in this account profile';
