 // Keep network writes ordered and isolated to the account/profile that initiated them.
 persist=function(){if(!server)return previewPersist();trackProjectChange();const snapshot=structuredClone(current),profile=me?.active_profile;if(!profile)return;if(saveBlocked){toast('Saving is paused. Export your edits, then reload to resolve the conflict.');return false}pendingSaves++;studioBackend.pending=true;$('#saved').textContent='Saving to server…';saveQueue=saveQueue.then(async()=>{if(saveBlocked)throw Error('Saving paused after a previous failure. Export your edits and reload.');if(me?.active_profile!==profile)throw Error('Profile changed before save completed.');const version=projectVersions.get(snapshot.id)??snapshot.version;snapshot.version=version;const result=await api('/projects/'+encodeURIComponent(snapshot.id),'PATCH',snapshot);projectVersions.set(snapshot.id,result.version);const live=projects.find(p=>p.id===snapshot.id);if(live)live.version=result.version;$('#saved').textContent='● Saved to server'}).catch(e=>{saveBlocked=true;studioBackend.saveFailed=true;status('saved','Save failed · export edits, then reload');showSaveProblem(e.message);toast(e.message)}).finally(()=>{pendingSaves--;studioBackend.pending=pendingSaves>0});return saveQueue};
 studioBackend.registerProject=p=>projectVersions.set(p.id,p.version);
 studioBackend.flush=async()=>{await saveQueue;if(saveBlocked)throw Error('Resolve the failed save before this action. Export a backup and reload.')};

 const previewRender=render;render=function(){previewRender();if(server){const footer=document.querySelector('.app main>footer>span:first-child');if(footer)footer.textContent=config.demo_mode?(config.ai_enabled?'● Local demo · optional local AI · no charges':'● Local demo · synthetic accounts · AI disabled'):config.free_beta?'● Free beta · no payments collected':'● Account project · version-checked saves';const badge=document.querySelector('.workbenchStorage');if(badge)badge.textContent=config.demo_mode?'Synthetic account demo':config.free_beta?'Free beta account':'Connected account';if(saveBlocked){status('saved','Save failed · export edits, then reload');showSaveProblem('Saving is paused after a failed or conflicting update. Export your edits before reloading.');}document.querySelector('.beta').innerHTML=(config.demo_mode?'LOCAL DEMO':config.free_beta?'FREE BETA':'STUDIO')+' <span>v15.6</span>'}};
 const previewSaveNew=saveNewStudioProject;saveNewStudioProject=async function(project){if(!server)return previewSaveNew(project);if(!StudioProjectData.validate(project))throw Error('Check the project values and export limits.');await studioBackend.flush();const result=await api('/projects','POST',project);const clean=(await api('/projects')).find(p=>p.id===result.id);if(!clean)throw Error('Project was saved but could not be loaded. Refresh the library.');projectVersions.set(clean.id,clean.version);projects.push(clean);current=clean;return clean};

